await shot("02-act2-tuning");
s = await until(x => x.act==="act2" && x.fragments.locked && x.actTime > x.fragments.alignedAt + 3800, 20000);
await shot("03-message");
s = await until(x => x.act==="act3" && x.actTime > 3200, 15000);
await shot("04-choice");
s = await until(x => x.act==="ending" && x.actTime > 7500, 10000);
await shot("05-answer-beam");
await page.evaluate(() => window.__LAST_SIGNAL__.seek(16000));
await page.waitForTimeout(600);
await shot("06-answer-late");
s = await until(x => x.act==="end" && x.actTime > 2200, 12000);
await shot("07-endcard-answer");
console.log(JSON.stringify({ phase:"answer-done", act:s.act, ending:s.ending, completed:s.completed, shots }, null, 2));
EOF

dev-browser --headless --timeout 240 <<'EOF'
const page = await browser.getPage("ls");
const shots = {};
async function shot(name){ shots[name] = await saveScreenshot(await page.screenshot(), name + ".png"); }
async function until(pred, ms){
  const t0 = Date.now();
  while(Date.now()-t0 < ms){
    const s = await page.evaluate(() => window.__LAST_SIGNAL__.snapshot());
    if(pred(s)) return s;
    await page.waitForTimeout(250);
  }
  return await page.evaluate(() => window.__LAST_SIGNAL__.snapshot());
}
// --- SILENT path (manual drive: alignFragment + choose) ---
await page.evaluate(() => { const A = window.__LAST_SIGNAL__; A.reset(217); A.setAutoplay(false); A.seek(23800); });
let s = await until(x => x.act==="act2" && x.actTime > 1500, 8000);
await page.evaluate(() => {
  const A = window.__LAST_SIGNAL__;
  const t = A.snapshot().fragments.targets;
  A.alignFragment(0, t[0]); A.alignFragment(1, t[1]); A.alignFragment(2, t[2]);
});
s = await until(x => x.fragments.locked, 4000);
await page.evaluate(() => { const A = window.__LAST_SIGNAL__; const s = A.snapshot(); A.seek(s.fragments.alignedAt + 11200); });
s = await until(x => x.act==="act3" && x.choiceAvailable, 8000);
const chosen = await page.evaluate(() => window.__LAST_SIGNAL__.choose("silent"));
s = await until(x => x.act==="ending" && x.actTime > 7500, 10000);
await shot("08-silent-fading");
await page.evaluate(() => window.__LAST_SIGNAL__.seek(17500));
await page.waitForTimeout(600);
await shot("09-silent-dawn");
s = await until(x => x.act==="end" && x.actTime > 2200, 12000);
await shot("10-endcard-silent");
// --- mobile viewport, opening ---
await page.setViewportSize({ width: 390, height: 780 });
await page.evaluate(() => { const A = window.__LAST_SIGNAL__; A.reset(217); A.setAutoplay(true,"answer"); A.seek(14200); });
await page.waitForTimeout(600);
await shot("11-mobile-act1");
await page.evaluate(() => window.__LAST_SIGNAL__.seek(23800));
s = await until(x => x.act==="act2" && x.actTime > 9500, 15000);
await shot("12-mobile-act2");
await page.setViewportSize({ width: 1280, height: 720 });
console.log(JSON.stringify({ phase:"silent+mobile-done", chosen, ending:s.ending, shots }, null, 2));
EOF

dev-browser --headless --timeout 180 <<'EOF'
const page = await browser.getPage("ls");
const errors = [];
page.on("console", m => { if (m.type() === "error") errors.push(m.text()); });
page.on("pageerror", e => errors.push("pageerror: " + e.message));
await page.emulateMedia({ reducedMotion: "reduce" });
await page.goto("file:///Users/melvynx/Developer/experiments/benchmarks/benchmarks/the-last-signal/2026-07-16-cc-claude-fable-5-2/index.html");
await page.waitForTimeout(1200);
const st = await page.evaluate(() => window.__LAST_SIGNAL__.runSelfTest());
// jump to the choice and click a real button
await page.evaluate(() => { const A = window.__LAST_SIGNAL__; A.setAutoplay(false); A.seek(23800); });
await page.waitForTimeout(500);
await page.evaluate(() => {
  const A = window.__LAST_SIGNAL__;
  const t = A.snapshot().fragments.targets;
  t.forEach((v,i) => A.alignFragment(i,v));
});
await page.waitForTimeout(400);
await page.evaluate(() => { const A = window.__LAST_SIGNAL__; const s = A.snapshot(); A.seek(s.fragments.alignedAt + 11500); });
await page.waitForTimeout(1000);
let s = await page.evaluate(() => window.__LAST_SIGNAL__.snapshot());
const actAtChoice = s.act;
await page.waitForTimeout(2500);
await page.getByRole("button", { name: "Stay Silent" }).click();
await page.waitForTimeout(400);
s = await page.evaluate(() => window.__LAST_SIGNAL__.snapshot());
const afterClick = { act: s.act, ending: s.ending, autoplay: s.autoplay.enabled };
// skip to end card, click "The Other Choice"
await page.evaluate(() => window.__LAST_SIGNAL__.seek(23500));
await page.waitForTimeout(2500);
await page.getByRole("button", { name: "The Other Choice" }).click();
await page.waitForTimeout(3500);
await page.getByRole("button", { name: "Answer" }).click();
await page.waitForTimeout(400);
s = await page.evaluate(() => window.__LAST_SIGNAL__.snapshot());
const buf = await page.screenshot();
const shot = await saveScreenshot(buf, "13-rm-answer-after-other.png");
console.log(JSON.stringify({ errors, selfTestPassed: st.passed, actAtChoice, afterClick, otherChoiceFlow: { act: s.act, ending: s.ending }, shot }, null, 2));
EOF
